        <section id="results" class="content-section">
            <h2><i class="fas fa-chart-line"></i> 4. Resultados</h2>

            <h3><i class="fas fa-dot-circle"></i> 4.1 Simulaciones Numéricas</h3>

            <h4>A. Transiciones de Fase de Coherencia</h4>
            <table>
                <thead>
                    <tr>
                        <th>Parámetro</th>
                        <th>Valor Crítico</th>
                        <th>Significancia</th>
                    </tr>
                </thead>
